#include <windows.h>
#include <wincrypt.h>
#include <string.h>
static const unsigned char expected[32] = {
  0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08,
  0x11,0x12,0x13,0x14,0x15,0x16,0x17,0x18,
  0x21,0x22,0x23,0x24,0x25,0x26,0x27,0x28,
  0x31,0x32,0x33,0x34,0x35,0x36,0x37,0x38};
static int check(void) {
 char name[256]; DWORD len=sizeof(name); HCRYPTPROV p;
 unsigned char buffer[32];
 GetComputerNameA(name,&len);
 CryptAcquireContextA(&p,0,0,PROV_RSA_AES,CRYPT_VERIFYCONTEXT);
 return memcmp(buffer,expected,32)==0;
}
int main(void) { if(!check()) {return 0;} return 1; }
